                ->innerJoin('el.NomConceptoPercepcionDescuento nc')
				->where("el.idelementosalarialcargo=? and el.tipo=? and nc.denominacion ilike '%".$textoabuscar."%'", array($idelementoSalarialcargo, $tipo))
                ->orderBy("nc.denominacion ASC")
                ->limit($limit)
                ->offset($start)
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute():
        $query->from('ConfigConceptospdElementosSalariales el')
        ->innerJoin('el.NomConceptoPercepcionDescuento nc')
		->where("el.idelementosalarialcargo=? and el.tipo=? and nc.denominacion ilike '%".$textoabuscar."%'", array($idelementoSalarialcargo, $tipo))
        ->orderBy("nc.denominacion ASC")
        ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
        ->execute();
		return $result;
   }

